package com.northstarbank.console.web;import com.northstarbank.console.integration.TierClient;import com.northstarbank.console.service.CustomerService;import jakarta.validation.constraints.Size;import java.util.*;import org.springframework.web.bind.annotation.*;
@RestController public class TypeaheadController{private final CustomerService customers;public TypeaheadController(CustomerService c){customers=c;}@GetMapping("/api/customers/typeahead")List<Map<String,String>> search(@RequestParam @Size(min=2,max=80)String q){return customers.search(q).stream().limit(8).map(c->Map.of("id",c.id(),"label",c.fullName()+" · "+c.id())).toList();}@GetMapping("/api/customers/{id}/summary")Map<String,String> summary(@PathVariable @jakarta.validation.constraints.Pattern(regexp="C\\d{4}")String id){var p=customers.view(id);var c=p.core().customer();return Map.of("id",c.id(),"fullName",c.fullName(),"branch",c.branch(),"phone",c.phone(),"email",c.email());}}
